-- REFERENCE SCHEMA FOR NEXT PHASE. NOT YET WIRED TO THE MVP SERVER.
-- PostgreSQL 15+. This preserves company scoping and uses UUID primary keys.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE companies (id TEXT PRIMARY KEY, name TEXT NOT NULL, color TEXT, hotline TEXT);
CREATE TABLE teams (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id TEXT NOT NULL REFERENCES companies(id), name TEXT NOT NULL, UNIQUE(company_id,name));
CREATE TABLE users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id TEXT REFERENCES companies(id), team_id UUID REFERENCES teams(id), name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('super_admin','company_admin','manager','member')), is_active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE interviews (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id TEXT NOT NULL REFERENCES companies(id), employer TEXT NOT NULL, country TEXT, interview_date DATE NOT NULL, budget_usd NUMERIC(14,2) NOT NULL DEFAULT 0 CHECK(budget_usd>=0), source TEXT NOT NULL DEFAULT 'manual', source_row INTEGER, source_key TEXT, notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(company_id,source,source_row));
CREATE TABLE tasks (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id TEXT NOT NULL REFERENCES companies(id), interview_id UUID REFERENCES interviews(id), title TEXT NOT NULL, description TEXT, requesting_team_id UUID REFERENCES teams(id), assigned_team_id UUID REFERENCES teams(id), assigned_user_id UUID REFERENCES users(id), status TEXT NOT NULL DEFAULT 'todo' CHECK(status IN ('todo','in_progress','in_review','revision','blocked','done')), priority TEXT NOT NULL DEFAULT 'normal' CHECK(priority IN ('low','normal','high','urgent')), due_date DATE, origin TEXT, approved_by UUID REFERENCES users(id), approved_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX tasks_company_status_idx ON tasks(company_id,status,due_date);
CREATE TABLE task_links (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), task_id UUID NOT NULL REFERENCES tasks(id) ON DELETE CASCADE, url TEXT NOT NULL, description TEXT);
CREATE TABLE task_comments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), task_id UUID NOT NULL REFERENCES tasks(id) ON DELETE CASCADE, user_id UUID NOT NULL REFERENCES users(id), content TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE team_requests (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id TEXT NOT NULL REFERENCES companies(id), requesting_team_id UUID NOT NULL REFERENCES teams(id), receiving_team_id UUID NOT NULL REFERENCES teams(id), title TEXT NOT NULL, description TEXT, status TEXT NOT NULL DEFAULT 'todo', priority TEXT NOT NULL DEFAULT 'normal', due_date DATE, created_by UUID REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE ad_accounts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id TEXT NOT NULL REFERENCES companies(id), facebook_page_no SMALLINT NOT NULL CHECK(facebook_page_no IN (1,2)), channel TEXT NOT NULL CHECK(channel IN ('CALL','WEB')), stage TEXT NOT NULL CHECK(stage IN ('Awareness','Retargeting','Conversion')), slot SMALLINT NOT NULL, meta_account_id TEXT, owner_user_id UUID REFERENCES users(id), UNIQUE(company_id,facebook_page_no,channel,slot));
CREATE TABLE integration_settings (company_id TEXT PRIMARY KEY REFERENCES companies(id), source_spreadsheet_id TEXT, source_tab TEXT, last_sync_at TIMESTAMPTZ);
CREATE TABLE audit_log (id BIGSERIAL PRIMARY KEY, company_id TEXT REFERENCES companies(id), actor_id UUID REFERENCES users(id), entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, action TEXT NOT NULL, changed_fields JSONB, occurred_at TIMESTAMPTZ NOT NULL DEFAULT now());
-- Apply row-level security or company_id-scoped WHERE conditions to every query.
-- PostgreSQL alone does not enforce these application permissions without RLS policies.
